CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_users (id uuid PRIMARY KEY, username text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'editor' CHECK(role IN ('owner','editor')), must_change_password boolean NOT NULL DEFAULT true, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, csrf_token text NOT NULL, user_agent text NOT NULL DEFAULT '', expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE site_settings (id text PRIMARY KEY DEFAULT 'main', data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE page_content (id uuid PRIMARY KEY, slug text UNIQUE NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', seo_title text NOT NULL DEFAULT '', seo_description text NOT NULL DEFAULT '', canonical text NOT NULL DEFAULT '', og_image text NOT NULL DEFAULT '', noindex boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE homepage_sections (id uuid PRIMARY KEY, slug text UNIQUE NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', background text NOT NULL DEFAULT 'light' CHECK(background IN ('light','dark','soft')), position integer NOT NULL DEFAULT 0, visible boolean NOT NULL DEFAULT true);
CREATE TABLE services (id uuid PRIMARY KEY, slug text UNIQUE NOT NULL, title text NOT NULL, division text NOT NULL, description text NOT NULL, body text NOT NULL, audience text NOT NULL DEFAULT '', benefits text NOT NULL DEFAULT '', process text NOT NULL DEFAULT '', icon text NOT NULL DEFAULT 'code', image text NOT NULL DEFAULT '', features jsonb NOT NULL DEFAULT '[]', faqs jsonb NOT NULL DEFAULT '[]', seo_title text NOT NULL DEFAULT '', seo_description text NOT NULL DEFAULT '', published boolean NOT NULL DEFAULT false, position integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pricing_plans (id uuid PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', amount numeric(12,2), currency text NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','INR','AED')), interval text NOT NULL DEFAULT 'month' CHECK(interval IN ('month','year','project','assessment')), features jsonb NOT NULL DEFAULT '[]', addons jsonb NOT NULL DEFAULT '[]', cta text NOT NULL DEFAULT 'Request a quote', popular boolean NOT NULL DEFAULT false, position integer NOT NULL DEFAULT 0, visible boolean NOT NULL DEFAULT false, service_id uuid REFERENCES services(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE media_assets (id uuid PRIMARY KEY, name text NOT NULL, url text NOT NULL, object_key text, alt text NOT NULL DEFAULT '', mime text NOT NULL DEFAULT '', size integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contact_inquiries (id uuid PRIMARY KEY, name text NOT NULL, company text NOT NULL, email text NOT NULL, phone text NOT NULL DEFAULT '', country text NOT NULL, service text NOT NULL, description text NOT NULL, budget text NOT NULL DEFAULT '', consent boolean NOT NULL, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','qualified','closed')), notes text NOT NULL DEFAULT '', notification_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX inquiries_date ON contact_inquiries(created_at DESC);
CREATE TABLE faqs (id uuid PRIMARY KEY, question text NOT NULL, answer text NOT NULL, position integer NOT NULL DEFAULT 0, visible boolean NOT NULL DEFAULT true, service_id uuid REFERENCES services(id) ON DELETE CASCADE);
CREATE TABLE audit_logs (id uuid PRIMARY KEY, actor_id uuid REFERENCES admin_users(id) ON DELETE SET NULL, action text NOT NULL, entity text NOT NULL, entity_id text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits (key text PRIMARY KEY, count integer NOT NULL DEFAULT 1, reset_at timestamptz NOT NULL);
